mapper.select:
/* ReqInboxMapper.selectPendingRequests */ SELECT R.REQ_ID AS reqId , R.REQ_TYPE AS reqType , R.USER_CD AS userCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS userNm , R.SITE_CD AS siteCd , R.NODE_CD AS nodeCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, R.NODE_CD) AS nodeNm , R.WORK_YMD AS workYmd , R.WORK_SEQ AS workSeq , R.START_DATE AS startDate , R.START_TIME AS startTime , R.END_DATE AS endDate , R.END_TIME AS endTime , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate FROM TB_USER_ATTD_REQ R WHERE R.CMPNY_CD = #{cmpnyCd} AND R.SITE_CD = #{siteCd} AND R.REQ_STATUS = '01' AND R.DEL_YN = 'N' AND R.REQ_TYPE IN
#{rt}
ORDER BY R.INSERT_DATE DESC

/* ReqInboxMapper.selectPendingSchedRequests */ SELECT R.REQ_ID AS reqId , R.REQ_TYPE AS reqType , R.USER_CD AS userCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS userNm , R.SITE_CD AS siteCd , R.NODE_CD AS nodeCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, R.NODE_CD) AS nodeNm , R.WORK_YMD AS workYmd , R.WORK_SEQ AS workSeq , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate , TS.SCH_CD AS reqSchCd , TS.SCH_NO AS reqSchNo , TSE.FST_SCH_STR_TIME AS reqFstStrTime , TSE.FST_SCH_END_TIME AS reqFstEndTime , TSE.SEC_SCH_STR_TIME AS reqSecStrTime , TSE.SEC_SCH_END_TIME AS reqSecEndTime , TSE.PRE_FIXED_OT_STR_TIME AS reqPreFixedOtStrTime , TSE.PRE_FIXED_OT_END_TIME AS reqPreFixedOtEndTime , TSE.FIXED_OT_STR_TIME AS reqFixedOtStrTime , TSE.FIXED_OT_END_TIME AS reqFixedOtEndTime , CS.SCH_CD AS curSchCd , CS.SCH_NO AS curSchNo , CSE.FST_SCH_STR_TIME AS curFstStrTime , CSE.FST_SCH_END_TIME AS curFstEndTime , CSE.SEC_SCH_STR_TIME AS curSecStrTime , CSE.SEC_SCH_END_TIME AS curSecEndTime , CSE.PRE_FIXED_OT_STR_TIME AS curPreFixedOtStrTime , CSE.PRE_FIXED_OT_END_TIME AS curPreFixedOtEndTime , CSE.FIXED_OT_STR_TIME AS curFixedOtStrTime , CSE.FIXED_OT_END_TIME AS curFixedOtEndTime FROM TB_USER_ATTD_REQ R
LEFT JOIN TB_SCH_MGMT TS ON TS.CMPNY_CD = R.CMPNY_CD AND TS.SITE_CD = R.SITE_CD AND TS.SCH_CD = R.SCH_CD LEFT JOIN ( ) TSE ON TSE.CMPNY_CD = R.CMPNY_CD AND TSE.SITE_CD = R.SITE_CD AND TSE.SCH_CD = R.SCH_CD AND TSE.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= R.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( ) SE WHERE SE.CMPNY_CD = R.CMPNY_CD AND SE.SITE_CD = R.SITE_CD AND SE.SCH_CD = R.SCH_CD )
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = R.CMPNY_CD AND WP.SITE_CD = R.SITE_CD AND WP.USER_CD = R.USER_CD AND WP.WORK_YMD = R.WORK_YMD LEFT JOIN TB_SCH_MGMT CS ON CS.CMPNY_CD = WP.CMPNY_CD AND CS.SITE_CD = WP.SITE_CD AND CS.SCH_CD = WP.WORK_PLAN_CD LEFT JOIN ( ) CSE ON CSE.CMPNY_CD = WP.CMPNY_CD AND CSE.SITE_CD = WP.SITE_CD AND CSE.SCH_CD = WP.WORK_PLAN_CD AND CSE.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD ) WHERE R.CMPNY_CD = #{cmpnyCd} AND R.SITE_CD = #{siteCd} AND R.REQ_STATUS = '01' AND R.DEL_YN = 'N' AND R.REQ_TYPE = #{reqType} ORDER BY R.INSERT_DATE DESC

/* ReqInboxMapper.selectProcessedRequests */ SELECT R.REQ_ID AS reqId , R.REQ_TYPE AS reqType , R.USER_CD AS userCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS userNm , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, R.NODE_CD) AS nodeNm , R.WORK_YMD AS workYmd , R.START_DATE AS startDate , R.START_TIME AS startTime , R.END_DATE AS endDate , R.END_TIME AS endTime , NULL AS leaveTypeNm , NULL AS leaveDays , NULL AS unitNm , TS.SCH_NO AS schNo , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate , R.REQ_STATUS AS procStatus , DATE_FORMAT(R.PROCESS_DATE, '%Y-%m-%dT%H:%i:%s') AS processDate , R.PROCESS_COMMENT AS processComment , NULL AS approvalStep FROM TB_USER_ATTD_REQ R LEFT JOIN TB_SCH_MGMT TS ON TS.CMPNY_CD = R.CMPNY_CD AND TS.SITE_CD = R.SITE_CD AND TS.SCH_CD = R.SCH_CD WHERE R.CMPNY_CD = #{cmpnyCd} AND R.SITE_CD = #{siteCd} AND R.PROCESS_USER_CD = #{processUserCd} AND R.REQ_STATUS IN ('02', '03') AND R.DEL_YN = 'N' AND R.REQ_TYPE IN
#{rt}
ORDER BY R.PROCESS_DATE DESC, R.REQ_ID DESC LIMIT 300
